// The fleet feature's graph-platform surface (#3606, epic #3604) — the fleet-INTERNAL modules a graph-loaded
// FleetPage imports but does NOT redraw: the `WorkerDetail` drill-in (a behavioural leaf kept as code per the
// dashboard-only scope) and the `useFleetGithub` / `fleetCost` logic (injected for #3606). The PURE dashboard
// computations were harvested into the algorithms graph and these libs now DELEGATE to those nodes (#3607:
// fleetCost→llmEnergy+groupTotals, fleetHealth→streamMerge, fleetGithub→windowedTally+orderByRank,
// fleetLive→precedenceResolve); what's injected here is the thin typed store-glue the loader wires the real
// store into — a React hook can't be a no-import graph node, so this injection IS "the loader injects the store".
// Registered HERE, inside the feature, because the shell must not reach a
// feature's internals (#1545) and eager-importing them from `app/` would de-lazy the whole planner at boot.
// The fleet host calls this synchronously before the graph page loads, so the modules are present when the
// compiled page's `require()` runs.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Skills from "@/features/skills"; // FleetLessons reads loadPendingLessons/lessonTitle from the skills barrel
import * as FleetCost from "@/features/glance/fleet/lib/fleetCost";
import * as FleetHealthLib from "@/features/glance/fleet/lib/fleetHealth";
// #4238 — `WorkerDetail` is now a `provides` RECORD, so the loader vendors its source rather than
// handing back this module (which stays as the fallback). Vendoring makes the loader responsible for
// what the detail panel reaches, and these five are what it reaches.
import * as FleetWorker from "@/features/glance/fleet/fleetWorker";
import * as WorkerDetailHelpers from "@/features/glance/fleet/workerDetail.helpers";
import * as WorkerDetailPlaceholder from "@/features/glance/fleet/WorkerDetailPlaceholder";
import * as WorkerModals from "@/features/glance/fleet/WorkerModals";
// FleetLessons/WorkerDetail read parseAuditLog from the logs barrel (it was the security barrel
// until the Security workspace dissolved into Logs -- same symbols, new owner).
import * as Logs from "@/features/logs";

/** Register the fleet's injected graph-platform modules by the specifiers its graph page imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerFleetPlatform(): void {
  registerAppModule("@/features/skills", Skills);
  registerAppModule("@/features/glance/fleet/lib/fleetCost", FleetCost);
  registerAppModule("@/features/glance/fleet/lib/fleetHealth", FleetHealthLib);
  registerAppModule("@/features/glance/fleet/fleetWorker", FleetWorker);
  registerAppModule("@/features/glance/fleet/workerDetail.helpers", WorkerDetailHelpers);
  registerAppModule("@/features/glance/fleet/WorkerDetailPlaceholder", WorkerDetailPlaceholder);
  registerAppModule("@/features/glance/fleet/WorkerModals", WorkerModals);
  registerAppModule("@/features/logs", Logs);
}
